const $=s=>document.querySelector(s);let format='mp4',busy=false;

function status(text,error=false){$('#status').hidden=false;$('#status').textContent=text;$('#status').classList.toggle('error',error)}
function videoURL(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return null;let id;if(u.hostname==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com','music.youtube.com'].includes(u.hostname)){id=u.pathname==='/watch'?u.searchParams.get('v'):u.pathname.match(/^\/(?:shorts|embed|live)\/([^/]+)/)?.[1]}return /^[\w-]{11}$/.test(id||'')?'https://www.youtube.com/watch?v='+id:null}catch{return null}}
$('#paste').onclick=async()=>{try{$('#url').value=await navigator.clipboard.readText();$('#url').focus()}catch{status('Bağlantıyı alana Ctrl+V ile yapıştırabilirsin.')}};
async function health(){try{const r=await fetch('/api/health');const d=await r.json();$('#service').textContent=d.ready?'Hizmet hazır · En fazla 100 MB ve 10 dakika. Dosyalar 30 dakika sonra silinir.':'İndirme araçları eksik. Önce kurulumu çalıştır.'}catch{$('#service').textContent='İndirme hizmetine bağlanılamadı. Sayfayı biraz sonra yenile.'}}
health();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'configure_download',title:'İndirmeyi hazırla',description:'YouTube bağlantısını, formatı ve kaliteyi görünür forma yerleştirir. İndirmeyi başlatmaz.',inputSchema:{type:'object',properties:{url:{type:'string'},format:{type:'string',enum:['mp4','mkv','webm','mov','avi','m4v','mp3','wav','flac','aac','ogg','m4a']},quality:{type:'string'}},required:['url','format','quality'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const url=videoURL(input.url);const options=qualityOptions(input.format).map(([value])=>value);const known=[...formatGroups.video,...formatGroups.audio].some(([ext])=>ext===input.format);if(!url||!known||!options.includes(input.quality)||busy)throw Error('Geçersiz seçim veya süren indirme.');setSource('youtube');setKind(isVideoOutput(input.format)?'video':'audio');$('#url').value=url;$('#output-format').value=input.format;$('#output-format').dispatchEvent(new Event('change'));$('#quality').value=input.quality;return {url:$('#url').value,format,quality:$('#quality').value,started:false}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
